from itertools import groupby


def duplicate_groups(files):
    items = sorted(files.items(), key=lambda kv: (kv[1], kv[0]))
    groups = []
    for _, grp in groupby(items, key=lambda kv: kv[1]):
        paths = [p for p, _ in grp]
        if len(paths) > 1:
            groups.append(paths)
    groups.sort(key=lambda g: g[0])
    return groups

